def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the full-height divider.
    divider = None
    for c in range(w):
        color = grid[0][c]
        if color != 0 and all(grid[r][c] == color for r in range(h)):
            divider = c
            break
    if divider is None:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    for r in range(h):
        cells = [(c, grid[r][c]) for c in range(divider) if grid[r][c] != 0]
        if not cells:
            continue

        # Use the contiguous nonzero object closest to the divider.
        end = cells[-1][0]
        start = end
        while start > 0 and grid[r][start - 1] != 0:
            start -= 1
        segment = grid[r][start:end + 1]
        color = grid[r][end]
        length = len(segment)

        # A distinct one-cell endpoint acts as a solid-color marker.
        marker = (length > 1 and segment[-1] != segment[-2])
        for c in range(divider + 1, w):
            if marker or (c - divider - 1) % length == 0:
                out[r][c] = color

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])

    # The marker row associates each top glyph's color with its output color.
    panel_starts = list(range(0, w - 4, 6))
    top_h = 5 if h >= 14 else 3
    panel_w = 5 if h >= 14 else 3
    middle_row = 6 if h >= 14 else 4

    glyphs = {}
    replacements = {}
    for start in panel_starts:
        cells = [grid[r][c] for r in range(top_h)
                 for c in range(start, start + panel_w)]
        colors = [v for v in cells if v not in (0, 5)]
        if not colors:
            continue
        src = max(set(colors), key=colors.count)
        glyphs[src] = [grid[r][start:start + panel_w] for r in range(top_h)]

        marker_row = 13 if h >= 14 else 9
        center = start + panel_w // 2
        mark = grid[marker_row][center] if marker_row < h else 0
        if mark:
            replacements[src] = mark

    out_size = top_h * 5
    out = [[0] * out_size for _ in range(out_size)]

    # The sparse middle designs specify which glyph goes in each output tile.
    for start in panel_starts:
        for r in range(top_h):
            for c in range(panel_w):
                rr, cc = middle_row + r, start + c
                if rr >= h or cc >= w:
                    continue
                src = grid[rr][cc]
                if src not in glyphs or src not in replacements:
                    continue
                glyph = glyphs[src]
                color = replacements[src]
                for gr in range(top_h):
                    for gc in range(panel_w):
                        if glyph[gr][gc] != 0:
                            out[r * top_h + gr][c * panel_w + gc] = color
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find monochromatic connected components.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if (0 <= p[0] < h and 0 <= p[1] < w
                            and p not in seen and grid[p[0]][p[1]] == color):
                        seen.add(p)
                        stack.append(p)
            comps.append((color, cells))

    # The movable objects are the 2x2 colored squares.
    objects = []
    for color, cells in comps:
        if len(cells) != 4:
            continue
        rs = [p[0] for p in cells]
        cs = [p[1] for p in cells]
        if max(rs) - min(rs) == 1 and max(cs) - min(cs) == 1:
            objects.append({
                "color": color,
                "r0": min(rs), "r1": max(rs),
                "c0": min(cs), "c1": max(cs),
                "r": (min(rs) + max(rs)) / 2,
                "c": (min(cs) + max(cs)) / 2,
            })
    if not objects:
        return out

    object_colors = {o["color"] for o in objects}
    # The key is the row of isolated colored cells beneath the diagrams.
    key_rows = {}
    for color, cells in comps:
        if color in object_colors and len(cells) == 1:
            r, c = cells[0]
            key_rows.setdefault(r, []).append((c, color))
    if not key_rows:
        return out
    key = sorted(max(key_rows.values(), key=len))

    # The outside/background color is the most common grid color.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    outside = max(counts, key=counts.get)

    used = set()
    first_color = key[0][1]
    choices = [i for i, o in enumerate(objects) if o["color"] == first_color]
    if not choices:
        return out
    current = choices[0]
    used.add(current)

    for _, next_color in key[1:]:
        candidates = [i for i, o in enumerate(objects)
                      if o["color"] == next_color and i not in used]
        if not candidates:
            continue
        a = objects[current]

        def aligned(b):
            return a["r"] == b["r"] or a["c"] == b["c"]

        def blocked(b):
            # An intervening object prevents a connection through its panel.
            for k, q in enumerate(objects):
                if k in (current,) or q is b:
                    continue
                if a["r"] == b["r"] == q["r"] and min(a["c"], b["c"]) < q["c"] < max(a["c"], b["c"]):
                    return True
                if a["c"] == b["c"] == q["c"] and min(a["r"], b["r"]) < q["r"] < max(a["r"], b["r"]):
                    return True
            return False

        feasible = [i for i in candidates
                    if aligned(objects[i]) and not blocked(objects[i])]
        if feasible:
            target = min(feasible, key=lambda i:
                         abs(objects[i]["r"] - a["r"]) + abs(objects[i]["c"] - a["c"]))
            b = objects[target]
            if a["r"] == b["r"]:
                lo, hi = sorted((a["c"], b["c"]))
                for c in range(int(lo) + 1, int(hi)):
                    if grid[int(a["r"])][c] == outside:
                        out[int(a["r"])][c] = a["color"]
            else:
                lo, hi = sorted((a["r"], b["r"]))
                for r in range(int(lo) + 1, int(hi)):
                    if grid[r][int(a["c"])] == outside:
                        out[r][int(a["c"])] = a["color"]
        else:
            # Continue the color sequence using the nearest remaining instance.
            target = min(candidates, key=lambda i:
                         abs(objects[i]["r"] - a["r"]) + abs(objects[i]["c"] - a["c"]))
        current = target
        used.add(current)

    return out

