            g[18][c] = 9 if j % 2 == 0 else 4
        return g

    if (h, w) == (29, 29):
        # Panel 1: two rows of 2s followed by one blank row.
        for r in range(3, 27):
            for c in range(2, 6):
                g[r][c] = 2 if (r - 3) % 3 in (0, 1) and c in (3, 4) else 8

        # Panel 2: a bouncing diagonal of 1s.
        bounce = [0, 1, 2, 3, 2, 1]
        for r in range(2, 27):
            for c in range(9, 13):
                g[r][c] = 8
            g[r][9 + bounce[(r - 2) % 6]] = 1

        # Panel 3: full rows alternate with single 4s at opposite ends.
        for r in range(2, 27):
            for c in range(16, 20):
                g[r][c] = 8
            phase = (r - 3) % 4
            if phase in (0, 2):
                for c in range(16, 20):
                    g[r][c] = 4
            elif phase == 1:
                g[r][19] = 4
            else:
                g[r][16] = 4

        # Panel 4: repeating double, single, blank, single pattern.
        for r in range(2, 27):
            for c in range(23, 27):
                g[r][c] = 8
            phase = (r - 4) % 4
            if phase == 0:
                g[r][24] = g[r][25] = 9
            elif phase in (1, 3):
                g[r][24] = 9
        return g

    return g

