def transform(grid):
    h, w = len(grid), len(grid[0])

    def repeated_count(vertical):
        count = 0
        n = w if vertical else h
        for k in range(n):
            vals = [grid[r][k] for r in range(h)] if vertical else grid[k]
            if any(vals.count(v) >= 2 for v in set(vals) if v != 0):
                count += 1
        return count

    vertical = repeated_count(True) > repeated_count(False)
    out = [row[:] for row in grid]
    nlines = w if vertical else h

    for k in range(nlines):
        vals = [grid[r][k] for r in range(h)] if vertical else grid[k][:]
        pairs = [
            (j - i, i)
            for i, v in enumerate(vals) if v != 0
            for j in range(i + 1, len(vals))
            if vals[j] == v
        ]
        if not pairs:
            continue

        period = min(d for d, _ in pairs)
        start = min(i for d, i in pairs if d == period)
        phase = start % period
        positions = [i for i in range(len(vals)) if i % period == phase]
        seeds = [i for i in positions if vals[i] != 0]
        if not seeds:
            continue

        if vertical:
            color = vals[min(seeds)]
            fill = positions
        else:
            color = vals[max(seeds)]
            if len({v for v in vals if v != 0}) > 1:
                limit = max(i for i, v in enumerate(vals) if v != 0)
                fill = [i for i in positions if i <= limit]
            else:
                fill = positions

        for i in fill:
            if vertical:
                out[i][k] = color
            else:
                out[k][i] = color

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 1 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            top = min(y for y, x in cells)
            bottom = max(y for y, x in cells)
            left = min(x for y, x in cells)
            right = max(x for y, x in cells)

            # Find a two-column, two-row color pattern immediately above
            # or below the shape, then continue it out to the grid edge.
            for direction in (-1, 1):
                if direction < 0:
                    a, b = top - 2, top - 1
                else:
                    a, b = bottom + 1, bottom + 2
                if not (0 <= a < h and 0 <= b < h):
                    continue

                for x in range(left, right):
                    if all(grid[y][xx] not in (1, 8)
                           for y in (a, b) for xx in (x, x + 1)):
                        # Continue the alternating pair away from the shape.
                        y = a - 1 if direction < 0 else b + 1
                        while 0 <= y < h:
                            source = a if (y - a) % 2 == 0 else b
                            out[y][x] = grid[source][x]
                            out[y][x + 1] = grid[source][x + 1]
                            y += direction

    return out
